// Build edition - regenerated by build/set-edition.js at build time (and kept
// here as the sensible default for `npm start` / opening index.html directly,
// which is always the FULL game).
//
//   BB_EDITION     "full" | "demo"
//   BB_DEMO_LEVELS how many adventure levels the demo lets you play
//   BB_DEMO_URL    where the demo sends the player to get the full game.
//                  Empty string = show the call-to-action as plain text with no
//                  button (nothing is invented; set it before shipping a demo:
//                  node build/set-edition.js demo "https://your-store-page")
window.BB_EDITION = "full";
window.BB_DEMO_LEVELS = 10;
window.BB_DEMO_URL = "https://pixset-studio.github.io/byte-blaster/";
